using namespace std;

class Solution {
public:
    int maxSubgraphScore(int n, vector<vector<int>>& edges, vector<int>& vals) {
        vector<vector<int>> adj(n);
        for (const auto& e : edges) {
            adj[e[0]].push_back(e[1]);
            adj[e[1]].push_back(e[0]);
        }
        int best = INT_MIN;
        auto dfs = [&](auto& self, int u, int p) -> int {
            int cur = vals[u];
            for (int v : adj[u]) {
                if (v != p) {
                    int gain = self(self, v, u);
                    if (gain > 0) cur += gain;
                }
            }
            best = max(best, cur);
            return cur;
        };
        dfs(dfs, 0, -1);
        return best;
    }
};

import java.util.*;

class Solution {
    private int best = Integer.MIN_VALUE;

    public int maxSubgraphScore(int n, int[][] edges, int[] vals) {
        List<List<Integer>> adj = new ArrayList<>();
        for (int i = 0; i < n; i++) adj.add(new ArrayList<>());
        for (int[] e : edges) {
            adj.get(e[0]).add(e[1]);
            adj.get(e[1]).add(e[0]);
        }
        best = Integer.MIN_VALUE;
        dfs(0, -1, adj, vals);
        return best;
    }

    private int dfs(int u, int p, List<List<Integer>> adj, int[] vals) {
        int cur = vals[u];
        for (int v : adj.get(u)) {
            if (v != p) {
                int gain = dfs(v, u, adj, vals);
                if (gain > 0) cur += gain;
            }
        }
        best = Math.max(best, cur);
        return cur;
    }
}

var maxSubgraphScore = function(n, edges, vals) {
    const adj = Array.from({ length: n }, () => []);
    for (const [u, v] of edges) {
        adj[u].push(v);
        adj[v].push(u);
    }
    let best = -Infinity;
    function dfs(u, p) {
        let cur = vals[u];
        for (const v of adj[u]) {
            if (v !== p) {
                const gain = dfs(v, u);
                if (gain > 0) cur += gain;
            }
        }
        best = Math.max(best, cur);
        return cur;
    }
